using System.Windows;
using System.Windows.Controls;
using TrueBIM.App.UI;
using TrueBIM.App.UI.DesignSystem;

namespace TrueBIM.App.Modules.ElectricalSchematic.UI;

public sealed class ElectricalSchematicGuideWindow : TrueBimWindow
{
    public ElectricalSchematicGuideWindow()
    {
        Title = "Методичка: электрическая схема";
        Icon = IconFactory.CreateImage(TrueBimIcon.Help, 32);
        Width = 840;
        Height = 720;
        MinWidth = 660;
        MinHeight = 480;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;
        StackPanel body = new() { Margin = new Thickness(8), MaxWidth = 850 };
        Section(body, "1. Подготовьте проект",
            "Заполните «• Группа», «• Расчетная мощность» и «• Потребитель» у потребителей. У основного элемента схемы заполните «• Группа». Номер группы должен быть уникальным во всём проекте; для одной группы допускается один основной элемент схемы.");
        Section(body, "2. Выберите группы",
            "Выделите нужные основные элементы схемы в Revit и нажмите TrueBIM → ЭОМ → «Обновить схему». Они будут отмечены в таблице. Также можно открыть окно без выделения и поставить галочки у нужных строк. В таблице показаны схемы со всех видов проекта; проверьте столбцы «Вид» и «ID схемы».");
        Section(body, "3. Проверьте предпросмотр",
            "Сравните значения «Было» и «Будет», количество потребителей и наименования. Открытие окна и кнопка «Обновить предпросмотр» только читают модель. Строки с ошибками недоступны для выбора. Подробности и ID проблемных элементов находятся на вкладке «Диагностика».");
        Section(body, "4. Обновите схему",
            "Нажмите «Обновить отмеченные». Записываются «• Установленная мощность» и «• Потребитель» только отмеченных схем. Расчётная мощность и ток пересчитываются формулами семейства. Прочтите результат каждой строки. Для повторного запуска обновите предпросмотр; для отмены закройте окно и нажмите Ctrl+Z в Revit.");
        Section(body, "Как считается мощность",
            "Складывается расчётная мощность каждого отдельного верхнеуровневого экземпляра во всём активном RVT, без дополнительных коэффициентов и умножения на количество. Связи RVT и вложенные экземпляры исключены. Стадии и варианты отдельно не фильтруются: группа должна быть уникальной в этой области поиска.",
            "Соглашение проверенного семейства: 1000 Вт → 1 ВА в параметре схемы. Например, 1000 + 2000 Вт → 3 ВА. Это масштаб записи семейства, а не физическое преобразование Вт в ВА. Коэффициент спроса и формулы семейства не изменяются.");
        Section(body, "Как сопоставляются группы и названия",
            "«1.4с» и «Гр.1.4c» считаются одной группой: учитываются префикс «Гр.», регистр, крайние пробелы и латинская c / кириллическая с. Исходные обозначения не меняются. Внутренние пробелы в номере группы сохраняются.",
            "Повторяющиеся наименования объединяются, сортируются и разделяются запятой с пробелом. Мощность разных экземпляров с одинаковым наименованием учитывается полностью. Пустое значение мощности существующего параметра считается нулём. Пустые наименования пропускаются с предупреждением; если все пустые, поле схемы очищается.");
        Section(body, "Что делать при предупреждении",
            "Пустая группа — заполните её у указанного элемента. Нет потребителей — проверьте обозначение группы и наличие источников в активном проекте: прежние значения схемы сохраняются. Дубликат схемы — устраните повтор номера, даже если копия находится на другом виде и не отмечена.",
            "Нет параметра, неверный тип или запись запрещена — проверьте семейство и доступность элемента для редактирования. Два поля одной группы записываются вместе; при ошибке изменения этой группы откатываются. Нулевое числовое значение допустимо, отрицательная мощность блокирует группу.");
        Section(body, "Поддерживаемые семейства",
            "Контракт проверен в Revit 2023: основное семейство схемы «(УГО) ЭОМ - Кабельная линия с потребителем», категория «Элементы узлов», и модельные потребители с соответствующими общими параметрами экземпляра. Группа и мощности определяются по GUID общих параметров, а «• Потребитель» схемы — по точному уникальному имени.",
            "Вложенные подрозетники и графические обозначения прокладки не считаются самостоятельными нагрузками или дублями схем. Семейства, где самостоятельные нагрузки размещены только во вложенных компонентах, этим режимом не поддерживаются.");
        Button close = new() { Content = "Закрыть методичку", IsCancel = true, MinHeight = 32, Style = TrueBimStyles.CreateButtonStyle() };
        close.Click += (_, _) => Close();
        Content = BuildShell(TrueBimUi.CreateHeader(Title, "От потребителей модели к выбранным группам схемы", TrueBimIcon.Help), null,
            new ScrollViewer { Content = body, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }, null,
            TrueBimUi.CreateFooter(null, close));
    }

    private static void Section(Panel body, string title, params string[] paragraphs)
    {
        StackPanel content = new() { Margin = new Thickness(16) };
        content.Children.Add(new TextBlock { Text = title, FontSize = 18, FontWeight = FontWeights.SemiBold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8) });
        foreach (string paragraph in paragraphs)
            content.Children.Add(new TextBlock { Text = paragraph, FontSize = 14, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8) });
        body.Children.Add(new Border { Child = content, Background = TrueBimBrushes.Surface, BorderBrush = TrueBimBrushes.Border, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Margin = new Thickness(0, 0, 0, 12) });
    }
}
